UPDATE backup_configs SET database_dumps = (SELECT coalesce(json_group_array(json_patch(json_object('service', json_extract(target.value, '$.service'), 'engine', CASE WHEN trim(json_extract(target.value, '$.command')) IN ('pg_dumpall -U "$POSTGRES_USER"', 'pg_dumpall -U "$POSTGRES_USER" | gzip') THEN 'postgres' WHEN trim(json_extract(target.value, '$.command')) IN ('mysqldump --all-databases -u "$MYSQL_USER" -p"$MYSQL_PASSWORD"', 'mysqldump --all-databases -u "$MYSQL_USER" -p"$MYSQL_PASSWORD" | gzip') THEN 'mysql' WHEN trim(json_extract(target.value, '$.command')) IN ('mariadb-dump --all-databases -u "$MARIADB_USER" -p"$MARIADB_PASSWORD"', 'mariadb-dump --all-databases -u "$MARIADB_USER" -p"$MARIADB_PASSWORD" | gzip') THEN 'mariadb' ELSE 'needs_configuration' END, 'database', ''), CASE WHEN CASE WHEN trim(json_extract(target.value, '$.command')) IN ('pg_dumpall -U "$POSTGRES_USER"', 'pg_dumpall -U "$POSTGRES_USER" | gzip') THEN 'postgres' WHEN trim(json_extract(target.value, '$.command')) IN ('mysqldump --all-databases -u "$MYSQL_USER" -p"$MYSQL_PASSWORD"', 'mysqldump --all-databases -u "$MYSQL_USER" -p"$MYSQL_PASSWORD" | gzip') THEN 'mysql' WHEN trim(json_extract(target.value, '$.command')) IN ('mariadb-dump --all-databases -u "$MARIADB_USER" -p"$MARIADB_PASSWORD"', 'mariadb-dump --all-databases -u "$MARIADB_USER" -p"$MARIADB_PASSWORD" | gzip') THEN 'mariadb' ELSE 'needs_configuration' END = 'needs_configuration' THEN json_object('legacyCommand', json_extract(target.value, '$.command')) ELSE '{}' END)), '[]') FROM json_each(database_dumps) AS target) WHERE EXISTS (SELECT 1 FROM json_each(database_dumps) WHERE json_type(value, '$.command') = 'text');
--> statement-breakpoint
UPDATE backup_configs SET enabled = 0 WHERE EXISTS (SELECT 1 FROM json_each(database_dumps) WHERE json_extract(value, '$.engine') = 'needs_configuration');
