UPDATE backup_runs SET manifest = json_set(coalesce(manifest, '{}'), '$.databaseTargets', json((SELECT (SELECT coalesce(json_group_array(json_patch(json_object('service', json_extract(target.value, '$.service'), 'engine', CASE WHEN trim(json_extract(target.value, '$.command')) IN ('pg_dumpall -U "$POSTGRES_USER"', 'pg_dumpall -U "$POSTGRES_USER" | gzip') THEN 'postgres' WHEN trim(json_extract(target.value, '$.command')) IN ('mysqldump --all-databases -u "$MYSQL_USER" -p"$MYSQL_PASSWORD"', 'mysqldump --all-databases -u "$MYSQL_USER" -p"$MYSQL_PASSWORD" | gzip') THEN 'mysql' WHEN trim(json_extract(target.value, '$.command')) IN ('mariadb-dump --all-databases -u "$MARIADB_USER" -p"$MARIADB_PASSWORD"', 'mariadb-dump --all-databases -u "$MARIADB_USER" -p"$MARIADB_PASSWORD" | gzip') THEN 'mariadb' ELSE 'needs_configuration' END, 'database', ''), CASE WHEN CASE WHEN trim(json_extract(target.value, '$.command')) IN ('pg_dumpall -U "$POSTGRES_USER"', 'pg_dumpall -U "$POSTGRES_USER" | gzip') THEN 'postgres' WHEN trim(json_extract(target.value, '$.command')) IN ('mysqldump --all-databases -u "$MYSQL_USER" -p"$MYSQL_PASSWORD"', 'mysqldump --all-databases -u "$MYSQL_USER" -p"$MYSQL_PASSWORD" | gzip') THEN 'mysql' WHEN trim(json_extract(target.value, '$.command')) IN ('mariadb-dump --all-databases -u "$MARIADB_USER" -p"$MARIADB_PASSWORD"', 'mariadb-dump --all-databases -u "$MARIADB_USER" -p"$MARIADB_PASSWORD" | gzip') THEN 'mariadb' ELSE 'needs_configuration' END = 'needs_configuration' THEN json_object('legacyCommand', json_extract(target.value, '$.command')) ELSE '{}' END)), '[]') FROM json_each(job.payload, '$.databaseDumps') AS target) FROM agent_jobs AS job WHERE job.type = 'backup' AND json_extract(job.payload, '$.backupRunId') = backup_runs.id LIMIT 1))) WHERE json_type(manifest, '$.databaseTargets') IS NULL AND EXISTS (SELECT 1 FROM agent_jobs AS job WHERE job.type = 'backup' AND json_extract(job.payload, '$.backupRunId') = backup_runs.id);
